from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENT = Decimal("0.01")


def _numeric(value: Any) -> Decimal:
    """Apply Meridian numeric coercion: empty or missing values are zero."""
    if value is None:
        return Decimal("0")
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def _as_float(value: Decimal) -> float:
    return float(_round_cents(value))


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply the invoiced-order status rule and I-to-X workflow actions."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = dict(order)

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return updated_order, [], []

    raise BusinessRuleViolation(
        "E5003",
        "Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live-line and order totals, preserving invoiced totals."""
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]
    status = order.get("STAT_CD")

    if status in ("I", "X"):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        quantity = _numeric(line.get("QTY"))
        unit_price = _numeric(line.get("UNIT_PRC"))
        extension = _round_cents(quantity * unit_price)
        line["EXT_AMT"] = _as_float(extension)
        total += extension

    discount = _numeric(order.get("DISC_PCT"))
    discounted_total = _round_cents(
        total * (Decimal("100") - discount) / Decimal("100")
    )
    new_total = _as_float(discounted_total)

    stored_total = _numeric(order.get("TOT_AMT"))
    audits = ["ORD_RETOTAL"] if stored_total != discounted_total else []

    if audits:
        updated_order["TOT_AMT"] = new_total

    return updated_order, updated_lines, audits
